def solve(matrix):
    """Return determinant of integer matrix using Bareiss algorithm.
    Empty matrix -> 1.
    """
    if not matrix:
        return 1
    n = len(matrix)
    # Ensure square
    for row in matrix:
        if len(row) != n:
            raise ValueError('Matrix must be square')
    # Copy to mutable list of lists
    A = [list(map(int, row)) for row in matrix]
    if n == 1:
        return A[0][0]
    det_sign = 1
    for k in range(n-1):
        # Pivot selection
        if A[k][k] == 0:
            # find a row to swap
            swap_row = None
            for i in range(k+1, n):
                if A[i][k] != 0:
                    swap_row = i
                    break
            if swap_row is None:
                return 0
            A[k], A[swap_row] = A[swap_row], A[k]
            det_sign = -det_sign
        pivot = A[k][k]
        prev_pivot = A[k-1][k-1] if k > 0 else 1
        for i in range(k+1, n):
            for j in range(k+1, n):
                # Bareiss update
                A[i][j] = (A[i][j]*pivot - A[i][k]*A[k][j]) // prev_pivot
            A[i][k] = 0
    return det_sign * A[n-1][n-1]

