def solve(weights, values, capacity):
    """Return the maximum total value for a 0/1 knapsack.
    Uses a 1‑dimensional DP array of size ``capacity+1``.
    ``weights`` and ``values`` are lists of equal length.
    """
    # Defensive: if no items or capacity non‑positive
    if capacity <= 0 or not weights:
        return 0
    dp = [0] * (capacity + 1)
    for w, v in zip(weights, values):
        if w > capacity:
            continue
        # iterate backwards to avoid reusing the same item
        for c in range(capacity, w - 1, -1):
            new_val = dp[c - w] + v
            if new_val > dp[c]:
                dp[c] = new_val
    return max(dp)

