def solve(grid):
    """Return the number of islands in a binary grid.
    An island is a group of "1" cells connected horizontally or vertically.
    Empty grid or grid with no rows returns 0.
    """
    if not grid:
        return 0
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0
    if cols == 0:
        return 0
    visited = [[False] * cols for _ in range(rows)]
    def bfs(r, c):
        stack = [(r, c)]
        visited[r][c] = True
        while stack:
            x, y = stack.pop()
            for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                nx, ny = x+dx, y+dy
                if 0 <= nx < rows and 0 <= ny < cols:
                    if not visited[nx][ny] and grid[nx][ny] == 1:
                        visited[nx][ny] = True
                        stack.append((nx, ny))
    count = 0
    for i in range(rows):
        for j in range(cols):
            if not visited[i][j] and grid[i][j] == 1:
                count += 1
                bfs(i, j)
    return count

