def solve(a, b):
    """Levenshtein edit distance between strings a and b.
    Handles None values by treating them as empty strings.
    Uses O(min(len(a), len(b))) space.
    """
    if a is None:
        a = ''
    if b is None:
        b = ''
    a = str(a)
    b = str(b)
    if not a:
        return len(b)
    if not b:
        return len(a)
    # Ensure a is the shorter string for space efficiency
    if len(a) > len(b):
        a, b = b, a
    n, m = len(a), len(b)
    prev = list(range(n + 1))
    for j in range(1, m + 1):
        cur = [j]
        bj = b[j - 1]
        for i in range(1, n + 1):
            cost = 0 if a[i - 1] == bj else 1
            cur.append(min(prev[i] + 1, cur[i - 1] + 1, prev[i - 1] + cost))
        prev = cur
    return prev[n]

