def solve(path: str) -> str:
    """Simplify a Unix-style path.
    Works for absolute paths (starting with '/') and relative paths.
    Resolves '.' and '..', collapses multiple slashes, and removes trailing slashes.
    Returns '/' for the root of an absolute path, and '.' for an empty relative path.
    """
    if path == "":
        return "/"
    is_abs = path.startswith('/')
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
            else:
                if not is_abs:
                    # keep leading .. in relative paths
                    stack.append('..')
            continue
        stack.append(part)
    if is_abs:
        # Absolute path: always start with '/'
        return '/' + '/'.join(stack) if stack else '/'
    else:
        # Relative path: join without leading slash
        if not stack:
            return '.'
        return '/'.join(stack)

