def solve(grid):
    """Count islands in a grid for batch 2.
    Handles empty grid, empty rows, and jagged rows.
    An island is a group of orthogonally adjacent cells with value 1.
    """
    if not grid:
        return 0
    # visited matrix matching each row's length
    visited = [ [False]*len(row) for row in grid ]
    def bfs(i, j):
        stack = [(i, j)]
        while stack:
            x, y = stack.pop()
            if visited[x][y]:
                continue
            visited[x][y] = True
            # explore neighbours (up, down, left, right) within bounds of each row's length
            for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                nx, ny = x+dx, y+dy
                if 0 <= nx < len(grid):
                    if 0 <= ny < len(grid[nx]):
                        if not visited[nx][ny] and grid[nx][ny] == 1:
                            stack.append((nx, ny))
    count = 0
    for i, row in enumerate(grid):
        for j, val in enumerate(row):
            if val == 1 and not visited[i][j]:
                count += 1
                bfs(i, j)
    return count

